/// <summary>
/// Vendor account is required for vendor rebates with Invoice consolidation by rebate type = Yes
/// </summary>
/// <returns>True if validation successful; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {            
        if (this.ModuleInventCustVend == ModuleInventCustVend::Vend && !this.METVendAccount)                
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateDeal, METVendAccount)));
        }
    }

    return ret;
}

/// <summary>
/// Overridding insert method to set aggregator string - even when the data comes from integration
/// </summary>
public void insert()
{
    //CB201 - Aggregate by Customer
    this.METAggregatedBy = this.METApplyCustomAggregation == NoYes::Yes ? METConstants::aggregateByCustomer : METConstants::emptyString;

    next insert();
}

/// <summary>
/// CB705_VendorRebatePosting
/// Add rebate posting profiles where DynamicAccount is METPurchasedFromVendor in the lookup
/// </summary>
/// <param name = "_rebateDeal"><c>TAMRebateDeal</c> record</param>
/// <param name = "_formControl">Form control</param>
/// <returns><c>Query</c> for the posting profile lookup</returns>
public static Query buildLookupPostingProfileQuery(TAMRebateDeal _rebateDeal, FormControl _formControl)
{
    Query query = next buildLookupPostingProfileQuery(_rebateDeal, _formControl);

    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(TAMRebatePosting));

    // Add rebate posting profiles where DynamicAccount is METPurchasedFromVendor in the lookup
    if (TAMRebateParameters::find().METProcessVendRebateBasedVendRebType
    &&  _formControl && _formControl.dataSourceObject() 
    &&  _formControl.dataSourceObject().table() == tableNum(TAMRebateDeal))
    {
        qbds.addRange(fieldNum(TAMRebatePosting, DynamicAccount)).value(queryValue(TAMRebateDynamicAccount::METPurchasedFromVendor));
    }
    return query;
}

/// <summary>
/// CB705_VendorRebatePosting
/// When module is changed from Vendor, clear METVendAccount and METInvoiceConsolidationByRebateType
/// </summary>
/// <param name = "_fieldName">Field name</param>
/// <param name = "_arrayIndex">Array index</param>
public void modifiedFieldValue(FieldName _fieldName, int _arrayIndex)
{
    next modifiedFieldValue(_fieldName, _arrayIndex);

    switch (_fieldName)
    {
        case fieldStr(TAMRebateDeal, ModuleInventCustVend) :
            if (this.ModuleInventCustVend == ModuleInventCustVend::Cust)
            {                    
                this.METVendAccount = METConstants::emptyString;
                this.METInvoiceConsolidationByRebateType = NoYes::No;
            }

            break;
        case fieldStr(TAMRebateDeal, METApplyCustomAggregation) : //CB201 - Aggregate by Customer
            this.METAggregatedBy = this.METApplyCustomAggregation == NoYes::Yes ? METConstants::aggregateByCustomer : METConstants::emptyString;
            break;
    }
}

/// <summary>
/// Bug 294087: CB234- Able to delete a deal with approval status "completed"
/// </summary>
/// <returns>true if record can be deleted; otherwise, false.</returns>
boolean validateDelete()
{
    boolean ret = next validateDelete();

    if (ret && this.State == TAMRebateDealWorkflowState::Completed)
    {
        ret = checkFailed("@MET:RebateDealValidateDelete");
    }

    return ret;
}

/// <summary>
/// Bug 294044: CB705- Vendor on line is not getting updated from the header vendor account
/// </summary>
public void update()
{
    boolean vendAccountUpdate;
    boolean rebateTableSourceTypeUpdate;

    if (this.orig().METVendAccount != METVendAccount)
    {
        vendAccountUpdate = true;
    }

    if (this.orig().METUseExternalSellData != this.METUseExternalSellData && this.METUseExternalSellData == NoYes::Yes)
    {
        rebateTableSourceTypeUpdate = true;
    }
    //CB201 - Aggregate by Customer 
    this.METAggregatedBy = this.METApplyCustomAggregation == NoYes::Yes ? METConstants::aggregateByCustomer : METConstants::emptyString;

    next update();

    if (vendAccountUpdate)
    {
        this.metUpdateRebateTableVendAccount();
    }

    if (rebateTableSourceTypeUpdate)
    {
        this.metUpdateRebateTableSourceType();
    }
}

/// <summary>
/// Bug 294044: CB705- Vendor on line is not getting updated from the header vendor account
/// </summary>
protected void metUpdateRebateTableVendAccount()
{
    TAMRebateTable rebateTable;

    ttsbegin;
    update_recordset rebateTable
             setting METVendAccount = this.METVendAccount
               where rebateTable.rebateDeal == this.RecId;
    ttscommit;
}

/// <summary>
/// Bug 293485: CB201- Transaction type field is non editable when creating a new deal, until we reload the webpage for finops
/// </summary>
public void metUpdateRebateTableSourceType()
{
    TAMRebateTable rebateTable;

    ttsbegin;
    update_recordset rebateTable
                setting SourceType = TAMRebateSourceType::METExternalSalesData
                where rebateTable.RebateDeal == this.RecId;
    ttscommit;        
}
